using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using System.Globalization;
namespace Lisichka {
    // Deterministic, local topic/sentence analysis. No generated facts or network.
    public sealed class ConversationAnalyzer {
        sealed class Topic {
            public string Name,Pattern,Answer,Question;
            public Topic(string n,string p,string a,string q){Name=n;Pattern=p;Answer=a;Question=q;}
        }
        static readonly Topic[] topics={
            new Topic("работа",@"работ\w*|началь\w*|коллег\w*|проект\w*|дедлайн\w*|собеседован\w*","С рабочими делами полезно отделить то, что зависит от тебя, от чужих решений.","Что сейчас важнее: срок, нагрузка или разговор с кем-то?"),
            new Topic("учёба",@"учеб\w*|учусь|экзамен\w*|школ\w*|универ\w*|зачет\w*|урок\w*|учител\w*","Большую учебную задачу можно разбить на небольшие части и начать с самой понятной.","Какой предмет или задание хочется обсудить?"),
            new Topic("друзья и общение",@"друз\w*|друг\w*|подруг\w*|общени\w*|поссор\w*|ссор\w*|отношени\w*","В разговоре с близкими бывает полезно назвать конкретный поступок и свои чувства, не угадывая чужие намерения.","Ты хочешь разобраться в разговоре или просто рассказать, как всё было?"),
            new Topic("семья",@"семь\w*|мама|мамой|папа|папой|родител\w*|сестр\w*|брат\w*|бабуш\w*|дедуш\w*","Семейные истории могут вызывать сразу несколько разных чувств — это нормально.","Что в этой истории для тебя самое важное?"),
            new Topic("фильмы и сериалы",@"фильм\w*|кино\w*|сериал\w*|актер\w*|режиссер\w*|аниме","Можно обсудить сюжет, персонажей, атмосферу или то, какие чувства оставил просмотр.","Как называется фильм и какой момент запомнился?"),
            new Topic("музыка",@"музык\w*|песн\w*|песен\w*|альбом\w*|концерт\w*|гитар\w*|пианино|плейлист\w*","Музыка часто связывается с воспоминаниями и настроением.","Что тебе в ней ближе: слова, мелодия или ритм?"),
            new Topic("книги",@"книг\w*|читаю|читал\w*|роман\w*|рассказ(?:ы|ов|а|е|у|ом)?|писател\w*","В книге можно заметить и саму историю, и то, как меняются её герои.","Что читаешь и о каком герое хочется поговорить?"),
            new Topic("игры",@"игр\w*|играю|играл\w*|варкрафт\w*|warcraft|рейд\w*|квест\w*|майнкрафт\w*|minecraft","В играх бывает приятно и побеждать, и исследовать мир, и просто проводить время с друзьями.","Что произошло в игре — победа, сложный момент или интересная находка?"),
            new Topic("программирование",@"программир\w*|код\w*|баг\w*|ошибк\w*|python|javascript|компиля\w*","Для разбора ошибки пригодятся точный текст, действие перед ней и ожидаемый результат. Я могу помочь составить такое описание.","Что должно было произойти и что получилось вместо этого?"),
            new Topic("техника",@"компьютер\w*|ноутбук\w*|телефон\w*|интернет\w*|клавиатур\w*|наушник\w*","С техникой полезно сначала определить, проблема постоянная или возникает после одного действия.","Что именно происходит и когда это началось?"),
            new Topic("поездки",@"путешеств\w*|поездк\w*|отпуск\w*|самолет\w*|поезд|город\w*|море|пляж\w*","В планах поездки обычно помогают три опоры: место, время и то, какого отдыха хочется.","Тебе хочется спокойствия, новых впечатлений или активного отдыха?"),
            new Topic("еда и готовка",@"готовл\w*|рецепт\w*|кухн\w*|ужин\w*|обед\w*|завтрак\w*|суп\w*|пирог\w*|торт\w*","Домашняя еда — хороший повод сделать уютную паузу.","Ты уже что-то приготовил или выбираешь, что сделать из продуктов?"),
            new Topic("спорт",@"спорт\w*|трениров\w*|футбол\w*|бегаю|пробеж\w*|плаван\w*|велосипед\w*","В занятиях приятно замечать небольшие изменения и собственный темп.","Что тебя радует в занятиях и какую цель ты себе выбрал?"),
            new Topic("животные",@"кот\w*|кош\w*|собак\w*|щен\w*|питом\w*|животн\w*","У животных столько забавных привычек. Такие истории всегда делают разговор живее.","Как зовут твоего питомца и что он сегодня устроил?"),
            new Topic("погода и природа",@"погод\w*|дожд\w*|снег\w*|солнц\w*|осен\w*|весн\w*|зима|лето|лес\w*","Погода умеет менять ощущение дня — от желания гулять до уютного вечера дома.","Тебе сегодня больше хочется прогулки или домашнего уюта?"),
            new Topic("планы",@"план\w*|мечт\w*|цель\w*|будущ\w*|хочу начать|хочу научиться","Чтобы приблизить большой план, можно выбрать один небольшой шаг на ближайшее время.","Какой первый шаг был бы для тебя посильным?"),
            new Topic("творчество",@"рису\w*|рисов\w*|творче\w*|фото\w*|стих\w*|дизайн\w*|картин\w*|рукодел\w*","В творчестве можно сначала попробовать маленький набросок и уже потом решать, что менять.","Что ты хочешь передать своей работой — настроение, историю или образ?"),
            new Topic("наука",@"наук\w*|космос\w*|звезд\w*|планет\w*|физик\w*|хими\w*|биолог\w*","Мне нравится любопытство! Моя встроенная база небольшая, поэтому сложные научные объяснения я не буду выдумывать.","Какой именно вопрос тебя заинтересовал?"),
            new Topic("деньги и покупки",@"деньг\w*|бюджет\w*|покуп\w*|зарплат\w*|накоп\w*","Можно сначала разделить обязательные расходы и желания, чтобы яснее увидеть свой выбор.","Ты хочешь обсудить конкретную покупку или общий план?"),
            new Topic("самочувствие",@"здоров\w*|забол\w*|болею|самочувств\w*|температур\w*|врач\w*","Жаль, если самочувствие подводит. Я не умею определять причину симптомов или назначать лечение.","Тебе сейчас хочется поговорить или лучше устроить тихую передышку?"),
            new Topic("новости",@"новост\w*|новость|событи\w*|произошло|случилось","Я не получаю новости из интернета, но могу обсудить то, что ты расскажешь.","Что в этой новости тебя больше всего задело или порадовало?")
        };
        List<Topic> previous=new List<Topic>();string previousText="";
        public static int HeartCount(string text,bool affection){string n=Intent.Normalize(text);if(Intent.Negative(n))return 2;if(Regex.IsMatch(n,@"\b(?:побед\w*|поступил\w*|сдал\w*|получилось|повысили|свадьб\w*|родил\w*|исполнил\w*)\b"))return 12;if(affection)return Regex.IsMatch(n,@"обожа|сильно|очень")?10:6;if(Intent.Positive(n))return 5;if(Regex.IsMatch(n,@"спасибо|благодар"))return 3;return 1;}
        public Reply Respond(string text){
            string normalized=Intent.Normalize(text);
            if(Regex.IsMatch(normalized,@"\b(?:я спать|я иду спать|пойду спать|отправляюсь спать|спокойной ночи|добрых снов|сладких снов)\b"))return new Reply("Спокойной ночи! Пусть отдых будет тёплым, а утро — спокойным 🧡",Intent.Command(text));
            var sum=Regex.Match(text.Trim(),@"^(?:сколько будет\s+)?(-?\d{1,10}(?:[.,]\d{1,6})?)\s*([+*/×÷−-])\s*(-?\d{1,10}(?:[.,]\d{1,6})?)\s*[=?]?$",RegexOptions.IgnoreCase);
            if(sum.Success){double a=double.Parse(sum.Groups[1].Value.Replace(',','.'),CultureInfo.InvariantCulture),b=double.Parse(sum.Groups[3].Value.Replace(',','.'),CultureInfo.InvariantCulture);string op=sum.Groups[2].Value;if((op=="/"||op=="÷")&&b==0)return new Reply("На ноль делить нельзя 🧡");double result=op=="+"?a+b:op=="-"||op=="−"?a-b:op=="*"||op=="×"?a*b:a/b;return new Reply("Получается "+result.ToString("G12",CultureInfo.GetCultureInfo("ru-RU"))+" 🧡");}
            if(previous.Count>0&&Regex.IsMatch(normalized,@"^(?:первое|второе|третье|давай про первое|давай про второе)$")){int i=normalized.Contains("втор")?1:normalized.Contains("трет")?2:0;i=Math.Min(i,previous.Count-1);return new Reply("Тогда обсудим: "+previous[i].Name+". "+previous[i].Answer+" "+previous[i].Question+" 🧡");}
            bool revisit=Regex.IsMatch(normalized,@"^(?:разбери это|проанализируй|что главное|выдели главное|подведи итог)$");
            if(revisit&&previousText.Length>0){text=previousText;normalized=Intent.Normalize(text);}
            var found=topics.Select(t=>new{Topic=t,Count=Regex.Matches(normalized,@"\b(?:"+t.Pattern+@")\b").Count}).Where(x=>x.Count>0).OrderByDescending(x=>x.Count).Select(x=>x.Topic).Take(3).ToList();
            if(found.Count==0&&text.Length<250)return null;
            previous=found;previousText=text;
            bool negative=Intent.Negative(normalized),positive=Intent.Positive(normalized);
            string mood=negative&&positive?"В сообщении есть и приятное, и то, что огорчает. ":negative?"Похоже, эта история сейчас непростая для тебя. ":positive?"Как приятно читать о хорошем! ":"";
            if(found.Count==0){string excerpt=Regex.Split(text,@"[.!?\n]+").FirstOrDefault(s=>s.Trim().Length>15)??text;excerpt=excerpt.Trim();if(excerpt.Length>160)excerpt=excerpt.Substring(0,157)+"…";return new Reply(mood+"Прочитала сообщение. У меня пока нет готовых знаний по этой теме. Ты написал: «"+excerpt+"». Что здесь самое важное для тебя и какой ответ был бы полезен? 🧡");}
            if(found.Count==1&&text.Length<250&&!revisit)return new Reply(mood+found[0].Answer+" "+found[0].Question+" 🧡");
            string resultText=mood+"Выделила темы: "+string.Join(", ",found.Select(t=>t.Name))+".\n";
            foreach(var t in found.Take(2))resultText+="• "+char.ToUpper(t.Name[0])+t.Name.Substring(1)+": "+t.Answer+"\n";
            resultText+=found.Count>1?"Что разберём сначала — первое или второе? 🧡":found[0].Question+" 🧡";
            return new Reply(resultText);
        }
    }
}
